def find_handle(out):
    if isinstance(out, dict):
        for k in ['evidence_handle', 'handle']:
            if out.get(k):
                return out.get(k)
        for k in ['evidence_handles']:
            v = out.get(k)
            if v:
                return v[0]
        for k in out:
            h = find_handle(out[k])
            if h:
                return h
    if isinstance(out, list):
        for v in out:
            h = find_handle(v)
            if h:
                return h
    return None

